import base64
import os
import streamlit as st

# ==========================================
# ASSET ENCODING HELPERS
# ==========================================
def get_base64_video():
    base_dir = os.path.dirname(os.path.abspath(__file__))
    candidates = [
        os.path.join(base_dir, "assets", "bg_video.mp4"),
        os.path.join(base_dir, "bg_video.mp4"),
        os.path.join(os.getcwd(), "assets", "bg_video.mp4"),
        os.path.join(os.getcwd(), "bg_video.mp4"),
    ]
    
    # Also check if the raw filename generated by your browser was preserved
    assets_dir = os.path.join(base_dir, "assets")
    if os.path.exists(assets_dir):
        for f in os.listdir(assets_dir):
            if f.endswith(".mp4"):
                candidates.insert(0, os.path.join(assets_dir, f))

    for p in candidates:
        if os.path.isfile(p):
            with open(p, "rb") as f:
                encoded = base64.b64encode(f.read()).decode()
                return f"data:video/mp4;base64,{encoded}"
    return None

FALLBACK_LOGOS = {
    "apple": "https://upload.wikimedia.org/wikipedia/commons/f/fa/Apple_logo_black.svg",
    "amazon": "https://upload.wikimedia.org/wikipedia/commons/a/a9/Amazon_logo.svg",
    "steam": "https://upload.wikimedia.org/wikipedia/commons/8/83/Steam_icon_logo.svg",
    "google": "https://upload.wikimedia.org/wikipedia/commons/d/d0/Google_Play_Arrow_logo.svg",
    "visa": "https://upload.wikimedia.org/wikipedia/commons/5/5e/Visa_Inc._logo.svg",
    "starbucks": "https://upload.wikimedia.org/wikipedia/en/d/d3/Starbucks_Corporation_Logo_2011.svg"
}

def get_base64_img(card_name):
    base_dir = os.path.dirname(os.path.abspath(__file__))
    possible_dirs = [
        os.path.join(base_dir, "assets"),
        base_dir,
        os.path.join(os.getcwd(), "assets"),
        os.getcwd()
    ]
    for folder in possible_dirs:
        if not os.path.exists(folder):
            continue
        for fname in os.listdir(folder):
            stem, ext = os.path.splitext(fname)
            if card_name.lower() in stem.lower() and ext.lower() in [".jpg", ".jpeg", ".png", ".webp"]:
                file_path = os.path.join(folder, fname)
                try:
                    with open(file_path, "rb") as f:
                        encoded = base64.b64encode(f.read()).decode()
                        mime = "jpeg" if ext.lower() in [".jpg", ".jpeg"] else ext.lower().replace(".", "")
                        return f"data:image/{mime};base64,{encoded}"
                except Exception:
                    pass
    return FALLBACK_LOGOS.get(card_name, "")

